      out.write("  if(evidenceEls.input){\r\n");
      out.write("    evidenceEls.input.addEventListener('change', updateEvidencePreview);\r\n");
      out.write("  }\r\n");
      out.write("  if(evidenceEls.remove){\r\n");
      out.write("    evidenceEls.remove.addEventListener('click', function(){\r\n");
      out.write("      resetEvidenceSelection(true);\r\n");
      out.write("    });\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function setCurrentEvidence(url){\r\n");
      out.write("    const href = resolveEvidenceUrl(url);\r\n");
      out.write("    if(!href){\r\n");
      out.write("      if(evidenceEls.current) evidenceEls.current.classList.add('hidden');\r\n");
      out.write("      if(evidenceEls.currentLink) evidenceEls.currentLink.removeAttribute('href');\r\n");
      out.write("      return;\r\n");
      out.write("    }\r\n");
      out.write("    if(evidenceEls.currentLink){\r\n");
      out.write("      evidenceEls.currentLink.href = href;\r\n");
      out.write("    }\r\n");
      out.write("    if(evidenceEls.current){\r\n");
      out.write("      evidenceEls.current.classList.remove('hidden');\r\n");
      out.write("    }\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function setBadge(status){\r\n");
      out.write("    const el = document.getElementById('status-badge');\r\n");
      out.write("    if(!el) return;\r\n");
      out.write("    el.textContent = status||'-';\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  // Chá»n tráº¡ng thÃ¡i káº¿ tiáº¿p theo luá»“ng\r\n");
      out.write("  function setNextStatus(currentStatus){\r\n");
      out.write("    const flow = [\r\n");
      out.write("      'ASSIGNED',\r\n");
      out.write("      'PICKED_UP',\r\n");
      out.write("      'OUT_FOR_DELIVERY',\r\n");
      out.write("      'FAILED_DELIVERY',\r\n");
      out.write("      'RETURNING',\r\n");
      out.write("      'RETURNED',\r\n");
      out.write("      'CANCELLED'\r\n");
      out.write("    ];\r\n");
      out.write("    const sel = document.getElementById('evt-status');\r\n");
      out.write("    if(!sel) return;\r\n");
      out.write("    const i = flow.indexOf(currentStatus||'');\r\n");
      out.write("    sel.value = (i>=0 && i+1<flow.length) ? flow[i+1] : (currentStatus||'ASSIGNED');\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function resolveEvidenceUrl(url){\r\n");
      out.write("    if(!url) return '';\r\n");
      out.write("    const raw = String(url).trim();\r\n");
      out.write("    if(!raw) return '';\r\n");
      out.write("    if(/^https?:\\/\\//i.test(raw)) return raw;\r\n");
      out.write("    if(ctx && raw.startsWith(ctx + '/')) return raw;\r\n");
      out.write("    if(raw.startsWith('/')){\r\n");
      out.write("      return ctx ? (ctx + raw) : raw;\r\n");
      out.write("    }\r\n");
      out.write("    const normalized = raw.replace(/^\\/+/, '');\r\n");
      out.write("    if(!ctx){\r\n");
      out.write("      return '/' + normalized;\r\n");
      out.write("    }\r\n");
      out.write("    return ctx + '/' + normalized;\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  async function load(){\r\n");
      out.write("    try{\r\n");
      out.write("      // API tráº£ { shipment, events } hoáº·c gá»™p\r\n");
      out.write("      const d = await fetchJson(apiBase + '/shipments/' + encodeURIComponent(id));\r\n");
      out.write("      const s = d.shipment ?? d;\r\n");
      out.write("      const events = d.events ?? [];\r\n");
      out.write("\r\n");
      out.write("      // ThÃ´ng tin\r\n");
      out.write("      document.getElementById('order-code').textContent = s.orderCode || '-';\r\n");
      out.write("      document.getElementById('receiver-name').textContent = s.receiverName || s.customerName || '-';\r\n");
      out.write("      document.getElementById('receiver-phone').textContent = s.receiverPhone || '-';\r\n");
      out.write("      document.getElementById('receiver-address').textContent = s.receiverAddress || '-';\r\n");
      out.write("      document.getElementById('cod-amount').textContent = ((s.codAmount||0).toLocaleString('vi-VN')) + ' VND';\r\n");
      out.write("      setBadge(s.status);\r\n");
      out.write("      setCurrentEvidence(s.evidenceUrl);\r\n");
      out.write("      if (!['DELIVERED','FAILED_DELIVERY','CANCELLED','RETURNED'].includes(s.status))\r\n");
      out.write("          setNextStatus(s.status);\r\n");
      out.write("      else\r\n");
      out.write("          document.getElementById('evt-status').value = s.status;\r\n");
      out.write("      // Timeline\r\n");
      out.write("      const ul = document.getElementById('events');\r\n");
      out.write("      ul.innerHTML = '';\r\n");
      out.write("      (events||[]).forEach(function(e){\r\n");
      out.write("        const t = e.createdAt ? new Date(e.createdAt).toLocaleString('vi-VN') : '-';\r\n");
      out.write("        const evidenceHref = resolveEvidenceUrl(e.evidenceUrl);\r\n");
      out.write("        ul.insertAdjacentHTML('beforeend',\r\n");
      out.write("          '<li class=\"rounded-lg border border-gray-200 bg-white px-3 py-2\">' +\r\n");
      out.write("            '<div class=\"flex items-center justify-between\">' +\r\n");
      out.write("              '<span class=\"text-sm font-medium\">' + (e.status||'-') + '</span>' +\r\n");
      out.write("              '<span class=\"text-xs text-gray-500\">' + t + '</span>' +\r\n");
      out.write("            '</div>' +\r\n");
      out.write("            (e.note ? '<div class=\"text-sm text-gray-700 mt-1\">'+ e.note +'</div>' : '') +\r\n");
      out.write("            (evidenceHref ? '<a class=\"text-sm text-amber-700 hover:underline\" href=\"'+ evidenceHref +'\" target=\"_blank\">Xem bằng chứng</a>' : '') +\r\n");
      out.write("          '</li>'\r\n");
      out.write("        );\r\n");
      out.write("      });\r\n");
      out.write("      document.getElementById('err').textContent = '';\r\n");
      out.write("    }catch(e){\r\n");
      out.write("      document.getElementById('err').textContent = e.message || 'Lá»—i táº£i dá»¯ liá»‡u';\r\n");
      out.write("    }\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  // actions\r\n");
      out.write("  document.getElementById('btnAddEvent').onclick = async function(){\r\n");
      out.write("    try{\r\n");
      out.write("      const status = document.getElementById('evt-status').value;\r\n");
      out.write("      const note = document.getElementById('evt-note').value;\r\n");
      out.write("      await fetchJson(apiBase + '/shipments/' + encodeURIComponent(id) + '/events', {\r\n");
      out.write("        method:'POST',\r\n");
      out.write("        headers:{'Content-Type':'application/json'},\r\n");
      out.write("        body: JSON.stringify({ status: status, note: note })\r\n");
      out.write("      });\r\n");
      out.write("      await load();\r\n");
      out.write("    }catch(e){\r\n");
      out.write("      alert('Lá»—i khi cáº­p nháº­t sá»± kiá»‡n: ' + (e.message || e));\r\n");
      out.write("    }\r\n");
      out.write("  };\r\n");
      out.write("\r\n");
      out.write("  const btnDeliver = document.getElementById('btnDeliver');\r\n");
      out.write("  if(btnDeliver){\r\n");
      out.write("    btnDeliver.addEventListener('click', async function(){\r\n");
      out.write("      if(!evidenceEls.input || !evidenceEls.input.files || evidenceEls.input.files.length === 0){\r\n");
      out.write("        alert('Vui lòng chọn ảnh minh chứng trước khi xác nhận.');\r\n");
      out.write("        return;\r\n");
      out.write("      }\r\n");
      out.write("      const file = evidenceEls.input.files[0];\r\n");
      out.write("      const codCheckbox = document.getElementById('codCollected');\r\n");
      out.write("      const noteEl = document.getElementById('deliverNote');\r\n");
      out.write("      const formData = new FormData();\r\n");
      out.write("      formData.append('evidence', file);\r\n");
      out.write("      formData.append('codCollected', codCheckbox && codCheckbox.checked ? 'true' : 'false');\r\n");
      out.write("      if(noteEl){\r\n");
      out.write("        const noteValue = noteEl.value.trim();\r\n");
      out.write("        if(noteValue){ formData.append('note', noteValue); }\r\n");
      out.write("      }\r\n");
      out.write("      btnDeliver.disabled = true;\r\n");
      out.write("      try{\r\n");
      out.write("        await fetchJson(apiBase + '/shipments/' + encodeURIComponent(id) + '/deliver', {\r\n");
      out.write("          method:'POST',\r\n");
      out.write("          body: formData\r\n");
      out.write("        });\r\n");
      out.write("        resetEvidenceSelection(true);\r\n");
      out.write("        if(codCheckbox){ codCheckbox.checked = false; }\r\n");
      out.write("        if(noteEl){ noteEl.value = ''; }\r\n");
      out.write("        await load();\r\n");
      out.write("      }catch(e){\r\n");
      out.write("        alert('Lỗi khi đánh dấu giao hàng: ' + (e.message || e));\r\n");
      out.write("      }finally{\r\n");
      out.write("        btnDeliver.disabled = false;\r\n");
      out.write("      }\r\n");
      out.write("    });\r\n");
      out.write("  }\r\n");
      out.write("  load();\r\n");
      out.write("</script>\r\n");
